export function getPersonalityFacetStrength(
  locale: string,
  domain: string,
  facet: number
): PersonalityFacetStrength {
  const key = `${domain}.${facet}`;
  return strengthsByLocale[locale]?.[key] ?? strengthsByLocale.en[key];
}
